CREATE TABLE feedback_user_state(tenant_id uuid NOT NULL REFERENCES organizations(id),owner_id uuid NOT NULL REFERENCES users(id),revision integer NOT NULL DEFAULT 0 CHECK(revision>=0),payload text NOT NULL,PRIMARY KEY(tenant_id,owner_id));
CREATE TABLE feedback_records(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES organizations(id),owner_id uuid NOT NULL REFERENCES users(id),project_id uuid REFERENCES projects(id) ON DELETE CASCADE,document_id uuid REFERENCES documents(id) ON DELETE CASCADE,created_at timestamptz NOT NULL,payload text NOT NULL);
CREATE TABLE feedback_memories(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES organizations(id),owner_id uuid NOT NULL REFERENCES users(id),entry_key text NOT NULL,rule_type text NOT NULL CHECK(rule_type IN('whitelist','blacklist')),entity_type text NOT NULL,expires_at timestamptz NOT NULL,user_dictionary boolean NOT NULL DEFAULT true,payload text NOT NULL,UNIQUE(tenant_id,owner_id,entry_key));
CREATE TABLE feedback_audits(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES organizations(id),owner_id uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL,payload text NOT NULL);
CREATE INDEX feedback_records_owner_time ON feedback_records(tenant_id,owner_id,created_at,id);
DO $$DECLARE tab text;BEGIN FOREACH tab IN ARRAY ARRAY['feedback_user_state','feedback_records','feedback_memories','feedback_audits'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',tab);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',tab);EXECUTE format('CREATE POLICY own_feedback ON %I USING(tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid AND owner_id=nullif(current_setting(''app.user_id'',true),'''')::uuid) WITH CHECK(tenant_id=nullif(current_setting(''app.tenant_id'',true),'''')::uuid AND owner_id=nullif(current_setting(''app.user_id'',true),'''')::uuid)',tab);EXECUTE format('GRANT SELECT,INSERT,UPDATE,DELETE ON %I TO tmw_app',tab);END LOOP;END$$;
